def get_vertex_positions(graph, rhs_graph, boundary_vertex_map):
    pos_dict = {v: (graph.row(m), graph.qubit(m)) for v, m in boundary_vertex_map.items()}

for v1, v2, data in rhs_graph.edges(data=True):
